#include <vector>
#include <algorithm>

using namespace std;

class MergeIntervalsTemplate {
public:
    // Core structural model for sequential interval consolidation
    vector<vector<int>> merge(vector<vector<int>>& intervals) {
        if (intervals.size() <= 1) {
            return intervals;
        }

        // 1. Sort elements by start times
        sort(intervals.begin(), intervals.end(), [](const vector<int>& a, const vector<int>& b) {
            return a[0] < b[0];
        });

        vector<vector<int>> mergedIntervals;

        // 2. Initialize tracking using the first interval segment
        int currentStart = intervals[0][0];
        int currentEnd = intervals[0][1];

        for (size_t i = 1; i < intervals.size(); ++i) {
            // Check for overlap between current tracking range and next interval
            if (intervals[i][0] <= currentEnd) {
                // Overlap found -> expand the tracking boundary
                currentEnd = max(currentEnd, intervals[i][1]);
            } else {
                // Disjoint intervals -> commit completed range and start a new track
                mergedIntervals.push_back({currentStart, currentEnd});
                currentStart = intervals[i][0];
                currentEnd = intervals[i][1];
            }
        }

        // Commit the final active interval
        mergedIntervals.push_back({currentStart, currentEnd});

        return mergedIntervals;
    }
};

